import type * as SarvamAI from "../index.js";
export interface JobLiveStatusResponse {
    job_id: string;
    job_name: string;
    job_state: SarvamAI.DocumentTranslationJobState;
    source_language_code: string;
    /** Overall progress (0-100). */
    progress?: number | undefined;
    /** Present for PDF (page-granular) jobs. */
    page_metrics?: SarvamAI.PageMetrics | undefined;
    /** Present for Office format (document-granular) jobs. */
    translation_metrics?: SarvamAI.TranslationLanguageMetrics | undefined;
    translations?: SarvamAI.TranslationStatusItem[] | undefined;
    /** Server warnings. Omitted when empty. */
    warnings?: string[] | undefined;
    created_at: string;
    updated_at: string;
    /** Job-level failure reason. */
    error_message?: string | undefined;
}
